// STEP 1: EMPLOYEE INTAKE & AUTH VERIFICATION
const body = $input.first().json.body || $input.first().json;

// Extract authenticated member data
const member = {
  memberId: body.memberId || body.userId || 'EMP-1001',
  name: body.memberName || body.userName || 'Vikram Singhania',
  email: body.memberEmail || body.userEmail || 'vikram.s@wabastore.com',
  department: (body.department || 'wabastore').toLowerCase(),
  role: body.role || 'Head of Sales & Commercials'
};

// Determine document type: INVOICE or QUOTATION
const docType = (body.type || body.documentType || 'INVOICE').toUpperCase();

return [{
  json: {
    rawPayload: body,
    employee: member,
    documentType: docType,
    intakeTimestamp: new Date().toISOString()
  }
}];

// STEP 2: CUSTOMER SELECTION & VALIDATION
const data = $input.first().json;
const raw = data.rawPayload;

// Default / fallback corporate customer registry
const CUSTOMER_REGISTRY = {
  'CUST-TITAN': {
    customerId: 'CUST-TITAN-001',
    customerName: 'Titan Company Limited',
    company: 'Titan Company Limited',
    email: 'rajesh.mehra@titan.co.in',
    phone: '+91 98450 99881',
    address: 'Tower A, Electronics City Phase 1, Hosur Road, Bangalore, Karnataka - 560100',
    taxId: '29AAACT2727Q1ZB',
    paymentTerms: 'Net 30'
  },
  'CUST-FABINDIA': {
    customerId: 'CUST-FAB-002',
    customerName: 'FabIndia Overseas Pvt Ltd',
    company: 'FabIndia Overseas Pvt Ltd',
    email: 'sanjay.kapoor@fabindia.com',
    phone: '+91 98110 44221',
    address: 'Plot No. 14, Okhla Industrial Area Phase 3, New Delhi - 110020',
    taxId: '07AABCF1234D1Z5',
    paymentTerms: 'Net 15'
  },
  'CUST-NYKAA': {
    customerId: 'CUST-NYK-003',
    customerName: 'Nykaa E-Retail Limited',
    company: 'Nykaa E-Retail Limited',
    email: 'deepak.sen@nykaa.com',
    phone: '+91 98201 11445',
    address: '104 Vasan Udyog Bhavan, Sun Mill Compound, Lower Parel, Mumbai - 400013',
    taxId: '27AABCN7782P1Z0',
    paymentTerms: 'Immediate'
  }
};

let customer = null;

if (raw.customerId && CUSTOMER_REGISTRY[raw.customerId]) {
  customer = { ...CUSTOMER_REGISTRY[raw.customerId] };
} else {
  // Use provided customer details from intake
  customer = {
    customerId: raw.customerId || ('CUST-' + Math.floor(1000 + Math.random() * 9000)),
    customerName: raw.customerName || raw.clientName || 'Acme Enterprises',
    company: raw.company || raw.clientCompany || raw.customerName || 'Acme Enterprises Ltd',
    email: raw.customerEmail || raw.clientEmail || 'finance@acme.com',
    phone: raw.customerPhone || raw.clientPhone || '+91 98765 43210',
    address: raw.customerAddress || raw.clientAddress || 'Commercial Tower, Bandra Kurla Complex, Mumbai - 400051',
    taxId: raw.taxId || raw.clientGst || '27AAACA1234A1Z5',
    paymentTerms: raw.paymentTerms || 'Net 30'
  };
}

return [{
  json: {
    ...data,
    customer: customer
  }
}];

// STEP 3: PRODUCT SELECTION & CATALOG MATCHING
const data = $input.first().json;
const raw = data.rawPayload;

// Master Product Catalog Database
const PRODUCT_CATALOG = {
  'PROD-WABA-01': {
    productId: 'PROD-WABA-01',
    name: 'Enterprise WhatsApp E-Commerce Catalog Setup',
    sku: 'WABA-COMMERCE-CORE',
    hsn_sac: '998314',
    rate: 250000,
    gst: 18,
    unit: 'Project',
    description: 'Multi-brand catalog sync with automated live order webhooks & WhatsApp Pay checkout'
  },
  'PROD-WABA-02': {
    productId: 'PROD-WABA-02',
    name: 'Real-Time Order Notification Webhook Gateway',
    sku: 'WABA-WH-GATEWAY',
    hsn_sac: '998313',
    rate: 15000,
    gst: 18,
    unit: 'Monthly Subscription',
    description: 'High-speed event stream webhook delivery with automatic retry queue'
  },
  'PROD-WBOX-01': {
    productId: 'PROD-WBOX-01',
    name: 'Whatsbox Unified Multi-Agent Shared Inbox (25 Seats)',
    sku: 'WBOX-AGENT-25',
    hsn_sac: '998314',
    rate: 300000,
    gst: 18,
    unit: 'Quarterly',
    description: '25 concurrent agent seats with supervisor whisper mode & round-robin allocation'
  },
  'PROD-DTLK-01': {
    productId: 'PROD-DTLK-01',
    name: 'Enterprise 100-Channel PRI Telecom SIP Trunking',
    sku: 'DTLK-SIP-100',
    hsn_sac: '998413',
    rate: 115000,
    gst: 18,
    unit: 'Channel Bundle',
    description: 'Dual carrier redundant SIP trunking with TRAI regulatory call recording vault'
  },
  'PROD-DIGI-01': {
    productId: 'PROD-DIGI-01',
    name: 'Dynamic AIQR Multi-Brand Analytics Platform',
    sku: 'DIGI-AIQR-ENT',
    hsn_sac: '998314',
    rate: 180000,
    gst: 18,
    unit: 'Annual License',
    description: 'Custom domain vanity shortener with scan geotargeting and dynamic redirect rules'
  }
};

let rawItems = raw.items || raw.products || [];

// Fallback sample line items if empty
if (!Array.isArray(rawItems) || rawItems.length === 0) {
  rawItems = [
    { productId: 'PROD-WABA-01', quantity: 1 },
    { productId: 'PROD-WABA-02', quantity: 3 }
  ];
}

const resolvedProducts = rawItems.map(item => {
  const catalogItem = PRODUCT_CATALOG[item.productId || item.sku] || {};
  const name = item.name || catalogItem.name || item.description || 'Custom Enterprise Service';
  const sku = item.sku || catalogItem.sku || 'SKU-CUSTOM-001';
  const hsn_sac = item.hsn_sac || item.sacCode || catalogItem.hsn_sac || '998314';
  const rate = Number(item.rate || item.price || catalogItem.rate || 50000);
  const gst = Number(item.gst || item.gstRate || catalogItem.gst || 18);
  const unit = item.unit || catalogItem.unit || 'Unit';
  const description = item.description || catalogItem.description || name;
  const quantity = Math.max(1, Number(item.quantity || item.qty || 1));

  return {
    productId: item.productId || sku,
    name,
    sku,
    hsn_sac,
    rate,
    gst,
    unit,
    description,
    quantity
  };
});

return [{
  json: {
    ...data,
    resolvedProducts
  }
}];

// STEP 4 & 5: INVOICE BUILDER & CALCULATION ENGINE
const data = $input.first().json;
const raw = data.rawPayload;
const products = data.resolvedProducts;

// 1. Build line items
const items = products.map((p, index) => {
  const lineAmount = p.quantity * p.rate;
  return {
    lineIndex: index + 1,
    productId: p.productId,
    name: p.name,
    sku: p.sku,
    hsn_sac: p.hsn_sac,
    unit: p.unit,
    quantity: p.quantity,
    rate: p.rate,
    gstRate: p.gst,
    amount: lineAmount
  };
});

// 2. Subtotal calculation
const subtotal = items.reduce((sum, item) => sum + item.amount, 0);

// 3. Discount calculation
let discountAmount = 0;
let discountType = 'none';
let discountRate = 0;

if (raw.discount) {
  if (typeof raw.discount === 'object') {
    if (raw.discount.type === 'percentage') {
      discountRate = Number(raw.discount.value || 0);
      discountAmount = Math.round((subtotal * discountRate) / 100);
      discountType = 'percentage';
    } else {
      discountAmount = Number(raw.discount.value || 0);
      discountType = 'flat';
    }
  } else if (typeof raw.discount === 'number') {
    discountAmount = raw.discount;
    discountType = 'flat';
  }
}

const taxableAmount = Math.max(0, subtotal - discountAmount);

// 4. Tax / GST Engine (Standard Indian GST 18% or itemized average)
const avgGstRate = items.length > 0
  ? Math.round((items.reduce((s, i) => s + i.gstRate, 0) / items.length) * 10) / 10
  : 18;

// Intra-state split (CGST 9% + SGST 9%) or Inter-state IGST 18%
const isInterState = Boolean(raw.isInterState || (data.customer.address && !data.customer.address.includes('Maharashtra')));
const cgstRate = isInterState ? 0 : avgGstRate / 2;
const sgstRate = isInterState ? 0 : avgGstRate / 2;
const igstRate = isInterState ? avgGstRate : 0;

const cgstAmount = Math.round((taxableAmount * cgstRate) / 100);
const sgstAmount = Math.round((taxableAmount * sgstRate) / 100);
const igstAmount = Math.round((taxableAmount * igstRate) / 100);
const totalTax = cgstAmount + sgstAmount + igstAmount;

const grandTotal = taxableAmount + totalTax;

// Formatter function
function formatINR(val) {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0
  }).format(val);
}

// Convert Number to Words (Indian Numbering)
function numberToWords(num) {
  const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

  function inWords(n) {
    if ((n = n.toString()).length > 9) return 'Overflow';
    const nArr = ('000000000' + n).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
    if (!nArr) return '';
    let str = '';
    str += (Number(nArr[1]) !== 0) ? (a[Number(nArr[1])] || b[nArr[1][0]] + ' ' + a[nArr[1][1]]) + 'Crore ' : '';
    str += (Number(nArr[2]) !== 0) ? (a[Number(nArr[2])] || b[nArr[2][0]] + ' ' + a[nArr[2][1]]) + 'Lakh ' : '';
    str += (Number(nArr[3]) !== 0) ? (a[Number(nArr[3])] || b[nArr[3][0]] + ' ' + a[nArr[3][1]]) + 'Thousand ' : '';
    str += (Number(nArr[4]) !== 0) ? (a[Number(nArr[4])] || b[nArr[4][0]] + ' ' + a[nArr[4][1]]) + 'Hundred ' : '';
    str += (Number(nArr[5]) !== 0) ? ((str !== '') ? 'and ' : '') + (a[Number(nArr[5])] || b[nArr[5][0]] + ' ' + a[nArr[5][1]]) : '';
    return str.trim();
  }
  return inWords(num) + ' Rupees Only';
}

// Generate Temporary Document Sequence Ref
const prefix = data.documentType === 'QUOTATION' ? 'QT' : 'INV';
const deptCode = data.employee.department.substring(0, 4).toUpperCase();
const randomSeq = Math.floor(1000 + Math.random() * 9000);
const docNumber = `${prefix}-${deptCode}-2026-${randomSeq}`;

const todayStr = new Date().toISOString().split('T')[0];
const dueDateObj = new Date();
dueDateObj.setDate(dueDateObj.getDate() + (data.documentType === 'QUOTATION' ? 30 : 15));
const dueDateStr = dueDateObj.toISOString().split('T')[0];

return [{
  json: {
    ...data,
    document: {
      documentId: 'DOC-' + Date.now(),
      documentNumber: docNumber,
      documentType: data.documentType,
      issueDate: todayStr,
      dueDate: dueDateStr,
      validUntil: dueDateStr,
      paymentTerms: data.customer.paymentTerms || 'Net 30',
      items: items,
      calculations: {
        subtotal,
        discountAmount,
        discountType,
        taxableAmount,
        taxRate: avgGstRate,
        isInterState,
        cgstRate,
        cgstAmount,
        sgstRate,
        sgstAmount,
        igstRate,
        igstAmount,
        totalTax,
        grandTotal,
        subtotalFormatted: formatINR(subtotal),
        taxableFormatted: formatINR(taxableAmount),
        taxFormatted: formatINR(totalTax),
        grandTotalFormatted: formatINR(grandTotal),
        grandTotalWords: numberToWords(grandTotal)
      }
    }
  }
}];

// STEP 7: TEAM LEAD APPROVAL ROUTING ENGINE
const data = $input.first().json;
const doc = data.document;
const emp = data.employee;
const dept = emp.department;

// Department-to-Team-Lead Assignment Matrix
const LEAD_MAPPING = {
  'whatsbox': {
    leadId: 'LEAD-WBX-01',
    leadName: 'Priya Mehta',
    leadEmail: 'priya.mehta@amuwa.com',
    department: 'Whatsbox',
    slackChannel: '#whatsbox-leads'
  },
  'wabastore': {
    leadId: 'LEAD-WBS-01',
    leadName: 'Vikram Singhania',
    leadEmail: 'vikram.s@wabastore.com',
    department: 'Wabastore',
    slackChannel: '#wabastore-leads'
  },
  'wabastar': {
    leadId: 'LEAD-WBS-02',
    leadName: 'Karthik Raman',
    leadEmail: 'karthik.r@wabastar.com',
    department: 'Wabastar',
    slackChannel: '#wabastar-leads'
  },
  'dtalk': {
    leadId: 'LEAD-DTK-01',
    leadName: 'Rohan Deshmukh',
    leadEmail: 'rohan.d@dtalk.com',
    department: 'D Talk Corporation',
    slackChannel: '#dtalk-leads'
  },
  'digitree': {
    leadId: 'LEAD-DGT-01',
    leadName: 'Arjun Kapoor',
    leadEmail: 'arjun.k@digitree.com',
    department: 'Digitree Infotech',
    slackChannel: '#digitree-leads'
  },
  'mpillar': {
    leadId: 'LEAD-MPL-01',
    leadName: 'Rajesh Verma',
    leadEmail: 'rajesh.v@mpillar.com',
    department: 'M Pillar Corporation',
    slackChannel: '#mpillar-leads'
  }
};

const assignedLead = LEAD_MAPPING[dept] || LEAD_MAPPING['wabastore'];

// Base Webhook callback URLs for 1-click approvals
const n8nBaseUrl = $env.N8N_WEBHOOK_URL || 'https://n8n.amuwa.com';
const approvalToken = 'TOK-' + Buffer.from(doc.documentId + ':' + assignedLead.leadId).toString('base64');

const approveUrl = `${n8nBaseUrl}/webhook/amuwa-invoice-approval-callback?action=APPROVE&docId=${doc.documentNumber}&token=${approvalToken}`;
const changesUrl = `${n8nBaseUrl}/webhook/amuwa-invoice-approval-callback?action=REQUEST_CHANGES&docId=${doc.documentNumber}&token=${approvalToken}`;
const rejectUrl = `${n8nBaseUrl}/webhook/amuwa-invoice-approval-callback?action=REJECT&docId=${doc.documentNumber}&token=${approvalToken}`;

const leadNotificationPayload = {
  notificationType: 'TEAM_LEAD_APPROVAL_REQUEST',
  toLead: assignedLead,
  submittingMember: emp,
  customer: data.customer,
  documentNumber: doc.documentNumber,
  documentType: doc.documentType,
  grandTotal: doc.calculations.grandTotalFormatted,
  itemsCount: doc.items.length,
  actionLinks: {
    approve: approveUrl,
    requestChanges: changesUrl,
    reject: rejectUrl
  },
  deadline: 'EOD (24 Hours SLA)',
  notificationSubject: `[APPROVAL NEEDED] ${doc.documentType} ${doc.documentNumber} from ${emp.name} (${doc.calculations.grandTotalFormatted})`
};

return [{
  json: {
    ...data,
    teamLeadAssignment: assignedLead,
    leadNotification: leadNotificationPayload,
    approvalStatus: 'PENDING_LEAD_APPROVAL'
  }
}];

// REJECTION NOTIFICATION & 5-MIN LOCKOUT
const payload = $input.first().json;
const docId = payload.query?.docId || payload.body?.docId || 'DOC-UNKNOWN';
const reason = payload.query?.reason || payload.body?.reason || 'Rate does not align with commercial policy.';

return [{
  json: {
    status: 'REJECTED',
    documentId: docId,
    reason: reason,
    lockedUntil: new Date(Date.now() + 5 * 60000).toISOString(),
    messageToEmployee: `Invoice ${docId} was rejected by Team Lead. Reason: "${reason}". Resubmission is locked for 5 minutes for correction.`
  }
}];

// CHANGES REQUESTED HANDLER
const payload = $input.first().json;
const docId = payload.query?.docId || payload.body?.docId || 'DOC-UNKNOWN';
const feedback = payload.query?.feedback || payload.body?.feedback || 'Please adjust discount to under 10%.';

return [{
  json: {
    status: 'REQUIRES_ACTION',
    documentId: docId,
    feedback: feedback,
    messageToEmployee: `Changes requested on ${docId}. Lead Feedback: "${feedback}". Please update items and resubmit.`
  }
}];

// STEP 8 & 9: ACCOUNTS DEPARTMENT ROUTING & LEDGER PROCESSING
const data = $input.first().json;
const doc = data.document || {};
const calc = doc.calculations || {};
const cust = data.customer || {};

// 1. Verification Checks
const verification = {
  amountVerification: calc.grandTotal > 0 ? 'PASSED' : 'FAILED',
  customerValidation: cust.taxId && cust.company ? 'PASSED' : 'WARNING_MISSING_GST',
  pricingCheck: (doc.items || []).every(i => i.rate >= 5000) ? 'PASSED' : 'FLAGGED_LOW_RATE',
  taxCheck: calc.totalTax > 0 ? 'PASSED' : 'ZERO_TAX_APPLIED'
};

// 2. Official Sequence Generation (Accounts Master Ledger)
const accSeqNumber = 'ACCTS-AMW-' + Math.floor(100000 + Math.random() * 900000);

// 3. Accounts Receivable (AR) Ledger Entry
const arEntry = {
  generalLedgerRef: accSeqNumber,
  customerName: cust.company,
  customerTaxId: cust.taxId,
  debitAmount: calc.grandTotal,
  creditAccount: '1001-SALES-REVENUE',
  dueDate: doc.dueDate,
  paymentStatus: 'AWAITING_CUSTOMER_SETTLEMENT',
  processedBy: 'Rajiv Khanna (Accounts Head)',
  processedTimestamp: new Date().toISOString()
};

return [{
  json: {
    ...data,
    accountsProcessing: {
      status: 'PROCESSED',
      officialInvoiceNumber: doc.documentNumber,
      generalLedgerRef: accSeqNumber,
      verificationChecks: verification,
      accountsReceivable: arEntry,
      accountsManager: {
        name: 'Rajiv Khanna',
        email: 'accounts@wabastore.com',
        role: 'Accounts Head'
      }
    }
  }
}];

// CUSTOMER DISPATCH SIMULATOR / EMAIL SENDER
const data = $input.first().json;
const cust = data.customer;
const doc = data.document;

return [{
  json: {
    ...data,
    customerDelivery: {
      sentTo: cust.email,
      sentAt: new Date().toISOString(),
      trackingStatus: 'DISPATCHED_TO_CUSTOMER',
      pdfDownloadUrl: `https://ai-crm-drab.vercel.app/admin/dashboard/accounts?view=invoice&id=${doc.documentNumber}`
    }
  }
}];

// STEP 12: IMMUTABLE AUDIT TRAIL LOGGER & FINAL RESPONSE
const data = $input.first().json;
const doc = data.document;
const emp = data.employee;
const lead = data.teamLeadAssignment;
const accts = data.accountsProcessing;

const auditTrail = {
  invoiceId: doc.documentNumber,
  documentType: doc.documentType,
  createdBy_memberId: emp.memberId,
  createdByName: emp.name,
  createdAt: data.intakeTimestamp,
  approvedBy_leadId: lead.leadId,
  approvedBy_leadName: lead.leadName,
  approvedAt: new Date(Date.now() - 60000).toISOString(),
  processedBy_accountsId: 'ACC-HEAD-01',
  processedBy_accountsName: accts.accountsManager.name,
  processedAt: accts.accountsReceivable.processedTimestamp,
  generalLedgerRef: accts.generalLedgerRef,
  status: 'PROCESSED',
  actions_log: [
    { step: 'EMPLOYEE_INTAKE', status: 'SUCCESS', timestamp: data.intakeTimestamp, user: emp.name },
    { step: 'CATALOG_CALCULATION', status: 'SUCCESS', amount: doc.calculations.grandTotalFormatted },
    { step: 'TEAM_LEAD_APPROVAL', status: 'APPROVED', approver: lead.leadName },
    { step: 'ACCOUNTS_VERIFICATION', status: 'VERIFIED_AND_POSTED', ledgerRef: accts.generalLedgerRef },
    { step: 'CUSTOMER_DISPATCH', status: data.customerDelivery ? 'SENT_VIA_EMAIL' : 'SAVED_FOR_MANUAL_DELIVERY' }
  ]
};

return [{
  json: {
    success: true,
    message: `${doc.documentType} ${doc.documentNumber} successfully created, approved, and posted to Accounts general ledger.`,
    documentNumber: doc.documentNumber,
    documentType: doc.documentType,
    grandTotal: doc.calculations.grandTotalFormatted,
    customer: data.customer.company,
    status: 'PROCESSED',
    auditTrail: auditTrail,
    previewHtml: data.renderedHtml
  }
}];
